:root {
  --accent: var(--appsmith-theme-jewelexAccentBlue, #378ADD);
  --accent-600: var(--appsmith-theme-jewelexAccentBlueDark, #2C6CB0);
  --accent-100: #E8F1FB;
  --accent-050: #F0F7FE;
  --accent-line: #C7DEF5;
  --paper: var(--appsmith-theme-jewelexBgPage, #F1F4F8);
  --panel: var(--appsmith-theme-jewelexCardBg, #FFFFFF);
  --line: #DCE2E9;
  --line-soft: #EDF0F4;
  --text: var(--appsmith-theme-jewelexTextPrimary, #16202E);
  --text-dim: var(--appsmith-theme-jewelexTextSecondary, #4E5A6B);
  --text-mute: var(--appsmith-theme-jewelexTextPlaceholder, #7C8896);
  --text-sub: var(--appsmith-theme-jewelexTextSub, #566270);
  --success: #1B8A5A;
  --success-bg: #E7F5EC;
  --warning: #B8792A;
  --warning-bg: #FBF1DF;
  --danger: #C0392B;
  --danger-bg: #FBEAE8;
  --font: var(--appsmith-theme-jewelexFont, "Inter"), ui-sans-serif, system-ui, sans-serif;
  --fs-body: var(--appsmith-theme-jewelexFontBody, 13px);
  --fs-input: var(--appsmith-theme-jewelexFontInput, 12.5px);
  --fs-label: var(--appsmith-theme-jewelexFontLabel, 11.5px);
  --fs-caption: 10.5px;
  --radius: 12px;
  --gutter: 22px;
  --rail: 150px;
  --state: var(--text-sub);
  --state-bg: var(--line-soft);
}

* {
  box-sizing: border-box;
}

html {
  height: 100%;
}

body {
  margin: 0;
  min-height: 100%;
  font-family: var(--font);
  background: var(--paper);
  color: var(--text);
  font-size: var(--fs-body);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
  overflow-y: auto; /* Scroll enable karega */
}

button {
  font-family: inherit;
}

[hidden] {
  display: none !important;
}

/* ============ Loader ============ */
.loader-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 320px;
  gap: 12px;
  color: var(--text-sub);
  font-size: var(--fs-input);
  font-weight: 500;
}

.spinner {
  width: 28px;
  height: 28px;
  border: 3px solid var(--line);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.page {
  max-width: 100%;
  margin: 0 auto;
  padding: 16px 16px 40px;
}

/* ============ Masthead ============ */
.masthead {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 10px;
}

.masthead-rule {
  width: 4px;
  flex-shrink: 0;
  background: var(--state);
}

.masthead-body {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 13px var(--gutter);
}

.masthead-id {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.btn-back {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--text-dim);
  cursor: pointer;
  transition: background 0.14s, color 0.14s, border-color 0.14s;
}

.btn-back:hover {
  background: var(--line-soft);
  color: var(--text);
  border-color: #C4CDD8;
}

.btn-back:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.avatar {
  width: 36px;
  height: 36px;
  border-radius: 11px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  background: linear-gradient(155deg, var(--accent) 0%, var(--accent-600) 100%);
  color: #fff;
  font-weight: 700;
  font-size: 14px;
}

.masthead-text {
  min-width: 0;
}

.vendor-name {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.015em;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.vendor-sub {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 3px;
  font-size: var(--fs-label);
  color: var(--text-sub);
}

.vendor-sub .sep {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--line);
  flex-shrink: 0;
}

.masthead-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.state-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px 5px 10px;
  border-radius: 999px;
  background: var(--state-bg);
  color: var(--state);
  font-size: var(--fs-label);
  font-weight: 600;
  white-space: nowrap;
}

.state-chip::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.action-div {
  width: 1px;
  align-self: stretch;
  margin: 2px;
  background: var(--line);
}

/* ============ Buttons ============ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid transparent;
  border-radius: 7px;
  padding: 7px 14px;
  font-size: var(--fs-input);
  font-weight: 600;
  cursor: pointer;
  transition: background 0.14s, border-color 0.14s, color 0.14s;
}

.btn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.btn-approve {
  background: var(--success);
  color: #fff;
  border-color: var(--success);
}

.btn-approve:hover:not(:disabled) {
  background: #157048;
  border-color: #157048;
}

.btn-reject {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger);
}

.btn-reject:hover:not(:disabled) {
  background: #962D22;
  border-color: #962D22;
}

.btn-quiet {
  background: var(--panel);
  color: var(--text-dim);
  border-color: var(--line);
}

.btn-quiet:hover:not(:disabled) {
  background: var(--line-soft);
  color: var(--text);
}

.btn-link {
  background: none;
  border: none;
  padding: 4px 6px;
  border-radius: 6px;
  font-size: var(--fs-label);
  font-weight: 600;
  color: var(--accent-600);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.btn-link:hover {
  background: var(--accent-050);
}

.btn-link:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

/* ============ Tabs ============ */
.tabs {
  display: flex;
  gap: 4px;
  margin: 0 0 10px;
  border-bottom: 1px solid var(--line);
  padding: 0 4px;
}

.tab-btn {
  appearance: none;
  border: none;
  background: none;
  font-size: var(--fs-input);
  font-weight: 600;
  color: var(--text-mute);
  padding: 10px 14px;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: color 0.14s, border-color 0.14s;
}

.tab-btn:hover {
  color: var(--text-dim);
}

.tab-btn.is-active {
  color: var(--accent-600);
  border-bottom-color: var(--accent);
}

.tab-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* ============ Sheet & blocks ============ */
.sheet {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}

.block {
  position: relative;
  display: grid;
  grid-template-columns: var(--rail) minmax(0, 1fr);
  gap: 0 26px;
  padding: 18px var(--gutter);
}

.block + .block {
  border-top: 1px solid var(--line);
}

.block::before {
  content: "";
  position: absolute;
  top: 18px;
  bottom: 18px;
  left: calc(var(--gutter) + var(--rail) + 13px);
  width: 1px;
  background: var(--line-soft);
}

.block-head {
  padding-top: 7px;
  padding-right: 4px;
}

.block-head h2 {
  margin: 0;
  font-size: 14.5px;
  font-weight: 700;
  letter-spacing: -0.015em;
  line-height: 1.3;
}

.block-head p {
  margin: 2px 0 0;
  font-size: var(--fs-caption);
  color: var(--text-mute);
  line-height: 1.45;
}

.block-sub {
  grid-column: 2;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px dashed var(--line);
}

.block-sub h3 {
  margin: 0 0 8px;
  font-size: var(--fs-label);
  font-weight: 700;
  color: var(--text-dim);
}

/* ============ More details toggle ============ */
.more-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  width: 100%;
  padding: 12px var(--gutter);
  background: var(--accent-050);
  border: none;
  border-top: 1px solid var(--line);
  cursor: pointer;
  font-size: var(--fs-input);
  font-weight: 600;
  color: var(--accent-600);
  transition: background 0.14s;
}

.more-toggle:hover {
  background: var(--accent-100);
}

.more-toggle:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.more-toggle-icon {
  display: inline-flex;
  transition: transform 0.16s;
}

.more-toggle[aria-expanded=true] .more-toggle-icon {
  transform: rotate(180deg);
}

.more-details .block:first-child {
  border-top: 1px solid var(--line);
}

/* ============ Label / value pairs ============ */
.pairs {
  margin: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0 24px;
}

.pair {
  min-width: 0;
  padding: 7px 0;
  border-bottom: 1px solid var(--line-soft);
}

.pair dt {
  font-size: var(--fs-caption);
  color: var(--text-mute);
  font-weight: 500;
  margin-bottom: 1px;
}

.pair dd {
  margin: 0;
  font-size: var(--fs-input);
  font-weight: 500;
  color: var(--text);
  overflow-wrap: break-word;
}

.pair dd.is-empty {
  color: var(--text-mute);
  font-weight: 400;
  font-style: italic;
}

.pair.is-wide {
  grid-column: span 2;
}

/* ============ Directors ============ */
.dir-row {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 8px 0;
  border-bottom: 1px solid var(--line-soft);
}

.dir-row:first-child {
  border-top: 1px solid var(--line-soft);
}

.dir-badge {
  width: 26px;
  height: 26px;
  flex-shrink: 0;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--accent-050);
  color: var(--accent-600);
  font-size: var(--fs-label);
  font-weight: 700;
}

.dir-main {
  min-width: 0;
  flex: 1;
}

.dir-name {
  font-size: var(--fs-input);
  font-weight: 600;
}

.dir-meta {
  font-size: var(--fs-label);
  color: var(--text-sub);
}

.dir-tag {
  flex-shrink: 0;
  font-size: var(--fs-caption);
  font-weight: 600;
  color: var(--accent-600);
  background: var(--accent-050);
  border-radius: 5px;
  padding: 2px 7px;
}

/* ============ Documents ============ */
.docs {
  list-style: none;
  margin: 0;
  padding: 0;
}

.doc {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 8px 0;
  border-bottom: 1px solid var(--line-soft);
}

.doc:first-child {
  border-top: 1px solid var(--line-soft);
}

.doc-icon {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  border-radius: 8px;
  display: grid;
  place-items: center;
  background: var(--line-soft);
  color: var(--text-mute);
}

.doc.is-present .doc-icon {
  background: var(--success-bg);
  color: var(--success);
}

.doc-main {
  flex: 1;
  min-width: 0;
}

.doc-title {
  font-size: var(--fs-input);
  font-weight: 600;
}

.doc-meta {
  font-size: var(--fs-label);
  color: var(--text-sub);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.doc-missing {
  color: var(--text-mute);
  font-style: italic;
}

.doc-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.doc-flag {
  font-size: var(--fs-caption);
  font-weight: 600;
  color: var(--warning);
  background: var(--warning-bg);
  border-radius: 5px;
  padding: 2px 7px;
  white-space: nowrap;
}

/* ============ Decision Modals (Top-Pinned) ============ */
.decision-modal-back {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: none;
  align-items: flex-start;
  justify-content: center;
  padding-top: 50px;
  background: rgba(15, 23, 42, 0.45);
  backdrop-filter: blur(2px);
}

.decision-modal-back.is-open {
  display: flex;
}

.decision-modal {
  background: var(--panel);
  width: 440px;
  max-width: 92vw;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  box-shadow: 0 20px 40px -8px rgba(15, 27, 51, 0.2);
  overflow: hidden;
  animation: modalDrop 0.16s ease-out;
}

@keyframes modalDrop {
  from {
    transform: translateY(-14px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}
.decision-modal-h {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid var(--line-soft);
}

.decision-modal-h h3 {
  margin: 0;
  font-size: 14.5px;
  font-weight: 700;
  color: var(--text);
}

.btn-close {
  background: none;
  border: none;
  font-size: 20px;
  line-height: 1;
  color: var(--text-mute);
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 4px;
}

.btn-close:hover {
  color: var(--text);
  background: var(--line-soft);
}

.decision-modal-b {
  padding: 16px 18px;
  font-size: var(--fs-input);
  color: var(--text-dim);
}

.decision-modal-b p {
  margin: 0 0 10px;
  line-height: 1.45;
}

.decision-textarea {
  width: 100% !important;
  box-sizing: border-box;
  font-family: inherit;
  font-size: var(--fs-input);
  line-height: 1.5;
  color: var(--text);
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 11px;
  outline: none;
  resize: vertical;
  min-height: 80px;
  transition: border-color 0.14s, box-shadow 0.14s;
}

.decision-textarea:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(55, 138, 221, 0.15);
}

.decision-textarea::placeholder {
  color: var(--text-mute);
}

.decision-err {
  margin-top: 5px;
  font-size: var(--fs-caption);
  color: var(--danger);
  font-weight: 500;
}

.decision-modal-f {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 18px;
  background: var(--line-soft);
  border-top: 1px solid var(--line);
}

/* ============ Toast ============ */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 12px);
  padding: 11px 18px;
  border-radius: 10px;
  background: #1A1F29;
  color: #fff;
  font-size: var(--fs-input);
  font-weight: 500;
  box-shadow: 0 14px 34px rgba(15, 27, 51, 0.3);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s, transform 0.22s;
  z-index: 60;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ============ Responsive ============ */
@media (max-width: 1080px) {
  .pairs {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 880px) {
  .block {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .block::before {
    display: none;
  }
  .block-head {
    padding-top: 0;
    margin-bottom: 10px;
  }
  .block-head p {
    display: none;
  }
  .block-sub {
    grid-column: 1;
  }
  .pairs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 640px) {
  :root {
    --gutter: 18px;
  }
  .page {
    padding: 16px 12px 48px;
  }
  .pairs {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .pair.is-wide {
    grid-column: span 1;
  }
  .masthead-body {
    flex-direction: column;
    align-items: flex-start;
    gap: 14px;
    padding: 18px var(--gutter);
  }
  .masthead-actions {
    justify-content: flex-start;
    width: 100%;
    flex-wrap: wrap;
  }
  .masthead-actions .btn {
    flex: 1;
  }
  .action-div {
    display: none;
  }
  .doc {
    flex-wrap: wrap;
  }
  .doc-actions {
    width: 100%;
    padding-left: 39px;
  }
}
@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}
/* ============ Decision banner ============ */
.decision-banner {
  margin-bottom: 10px;
  padding: 11px var(--gutter);
  border: 1px solid var(--line);
  border-left-width: 4px;
  border-radius: var(--radius);
  background: var(--panel);
}

.decision-banner.is-approved {
  border-left-color: var(--success);
  background: var(--success-bg);
}

.decision-banner.is-rejected {
  border-left-color: var(--danger);
  background: var(--danger-bg);
}

.decision-banner-title {
  font-size: var(--fs-label);
  font-weight: 700;
  margin-bottom: 2px;
}

.decision-banner.is-approved .decision-banner-title {
  color: var(--success);
}

.decision-banner.is-rejected .decision-banner-title {
  color: var(--danger);
}

.decision-banner-reason {
  font-size: var(--fs-input);
  color: var(--text);
  white-space: pre-wrap;
  overflow-wrap: break-word;
}

.decision-banner-reason.is-empty {
  color: var(--text-mute);
  font-style: italic;
}

.decision-banner-meta {
  margin-top: 3px;
  font-size: var(--fs-caption);
  color: var(--text-sub);
}

/* ============ Fullscreen Action Overlay (same as KYC Approved loader) ============ */
.action-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 120px;
  background: rgba(241, 244, 248, 0.85);
  backdrop-filter: blur(2px);
}

.action-overlay[hidden] {
  display: none;
}

.save-loader-card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 28px 36px;
  text-align: center;
  box-shadow: 0 10px 30px rgba(22, 32, 46, 0.12);
  font-family: var(--font);
  min-width: 280px;
}

.save-spinner {
  width: 36px;
  height: 36px;
  margin: 0 auto 14px;
  border: 3px solid var(--accent-100);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: saveSpin 0.8s linear infinite;
}

.save-loader-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}

.save-loader-sub {
  font-size: var(--fs-label);
  color: var(--text-mute);
  margin-top: 6px;
}

@keyframes saveSpin {
  to {
    transform: rotate(360deg);
  }
}

