      let rawBase64 = getDocuments.data.fileData;
      if (rawBase64.includes(',')) {
        rawBase64 = rawBase64.split(',').pop();
      }

      // 2. Original filename Mongo query (getRequestedDocument) se
      const fileName = getRequestedDocument.data?.[0]?.original_filename || "document.pdf";

      // 3. Base64 Data URI create karein
      const dataUri = `data:application/pdf;base64,${rawBase64.trim()}`;

      // 4. Download trigger karein (Bina atob/Uint8Array ke)
      download(dataUri, fileName, "application/pdf");
