  renderFieldSections();
  renderDocs();
  renderTabs();
  renderMoreDetails();
  syncChrome();
}

// ============================================================
// WF_FIN_Decision payload + Actions
// ============================================================
function getLatestEventIdByType(v, eventType) {
  var events = Array.isArray(v && v.events) ? v.events : [];
  var matches = events.filter(function (e) {
    return e && e.event_type === eventType;
  });
  if (!matches.length) return "";
  matches.sort(function (a, b) {
    var sa = typeof a.seq === "number" ? a.seq : -Infinity;
    var sb = typeof b.seq === "number" ? b.seq : -Infinity;
    if (sb !== sa) return sb - sa;
    return toTime(b.occurred_at) - toTime(a.occurred_at);
  });
  return matches[0].event_id || "";
}
function buildDecisionPayload(action, reason) {
  var model = getActiveModel();
  var v = model.vendorData || {};
  var sub = v.latest_submission || latestSubmission(v) || {};
  var payload = {
    decision: action === "approve" ? "APPROVE" : "REQUEST_CHANGES",
    case_id: state.caseId,
    submission_id: sub.submission_id || sub._id || state.submissionId || "",
    expected_lock_version: typeof v.lock_version === "number" ? v.lock_version : 0,
    expected_review_row_version: v.review && typeof v.review.row_version === "number" ? v.review.row_version : 0,
    review_id: uuid(),
    event_id: uuid(),
    correlation_id: getLatestEventIdByType(v, "SUBMISSION_CREATED"),
    actor_subject: model.actorSubject || model.currentUserEmail || v.actor_subject || "",
    decision_reason: action === "approve" ? "" : String(reason || "").trim(),
    idempotency_key: uuid()
  };
  if (action === "approve") payload.handoff_id = uuid();
  return payload;
}
async function pushDecision(action, reason) {
  if (state.busy) return;
  if (!state.caseId) return;
  if (state.statusKey !== "review") return;
  var payload = buildDecisionPayload(action, reason);
  if (!payload.submission_id) return;
  state.busy = true;
  state.pendingDecision = action;
  state.pendingIdempotencyKey = payload.idempotency_key;
  renderMasthead();
  syncChrome();
  if (!window.appsmith || typeof appsmith.updateModel !== "function") {
    setTimeout(function () {
      state.statusKey = action === "approve" ? "approved" : "rejected";
      state.caseStatus = action === "approve" ? "APPROVED" : "CHANGES_REQUESTED";
      state.statusDate = prettyDate(new Date().toISOString());
      state.review = {
        review_state: state.caseStatus,
        decision_reason: payload.decision_reason,
        actor_subject: payload.actor_subject,
        decided_at: new Date().toISOString()
      };
      finishPendingDecision(true);
      renderMasthead();
      renderDecision();
    }, 500);
    return;
  }
  isInternalUpdate = true;
  await appsmith.updateModel({
    financeDecisionRequest: payload
  });
  if (typeof appsmith.triggerEvent === "function") {
    appsmith.triggerEvent(action === "approve" ? "onApprove" : "onReject");
  }
  setTimeout(function () {
    isInternalUpdate = false;
  }, 500);
  setTimeout(function () {
    if (state.pendingDecision === action && state.pendingIdempotencyKey === payload.idempotency_key) {
      finishPendingDecision(false, "No response received");
    }
  }, 20000);
}
async function downloadDoc(i) {
  var d = state.documents[i];
  if (!d || !d.documentId) return;
  var docPayload = {
    document_id: d.documentId,
    document_type_code: d.code,
    docName: d.docName,
    fileName: d.fileName
  };
  isInternalUpdate = true;
  if (window.appsmith && typeof appsmith.updateModel === "function") {
    await appsmith.updateModel({
      requestedDocument: docPayload
    });
  }
  if (window.appsmith && typeof appsmith.triggerEvent === "function") {
    appsmith.triggerEvent("onDocumentDownload");
  }
  setTimeout(function () {
    isInternalUpdate = false;
  }, 400);
}

// ============================================================
// Event Listeners Registration
// ============================================================
var listenersBound = false;
function setupEventListeners() {
  if (listenersBound) return;
  listenersBound = true;
  var approveModal = $("#approveModal");
  var rejectModal = $("#rejectModal");
  var rejectReasonInput = $("#rejectReasonInput");
  var rejectReasonErr = $("#rejectReasonErr");
  function openApproveModal() {
    if (state.busy || state.statusKey !== "review") return;
    if (approveModal) approveModal.classList.add("is-open");
  }
  function closeApproveModal() {
    if (approveModal) approveModal.classList.remove("is-open");
  }
  function openRejectModal() {
    if (state.busy || state.statusKey !== "review") return;
    if (rejectReasonInput) rejectReasonInput.value = "";
    if (rejectReasonErr) rejectReasonErr.style.display = "none";
    if (rejectModal) rejectModal.classList.add("is-open");
  }
  function closeRejectModal() {
    if (rejectModal) rejectModal.classList.remove("is-open");
  }
  var btnApp = $("#approveBtn");
  var btnRej = $("#rejectBtn");
  if (btnApp) btnApp.addEventListener("click", openApproveModal);
  if (btnRej) btnRej.addEventListener("click", openRejectModal);
  var appClose = $("#approveModalClose");
  var appCancel = $("#approveModalCancel");
  var rejClose = $("#rejectModalClose");
  var rejCancel = $("#rejectModalCancel");
  if (appClose) appClose.addEventListener("click", closeApproveModal);
  if (appCancel) appCancel.addEventListener("click", closeApproveModal);
  if (rejClose) rejClose.addEventListener("click", closeRejectModal);
  if (rejCancel) rejCancel.addEventListener("click", closeRejectModal);
  var appConfirm = $("#approveModalConfirm");
  if (appConfirm) {
    appConfirm.addEventListener("click", function () {
      closeApproveModal();
      pushDecision("approve");
    });
  }
  var rejConfirm = $("#rejectModalConfirm");
  if (rejConfirm) {
    rejConfirm.addEventListener("click", function () {
      var reason = (rejectReasonInput ? rejectReasonInput.value : "").trim();
      if (!reason) {
        if (rejectReasonErr) rejectReasonErr.style.display = "block";
        if (rejectReasonInput) rejectReasonInput.focus();
        return;
      }
      closeRejectModal();
      pushDecision("reject", reason);
    });
  }
  document.querySelectorAll(".tab-btn").forEach(function (btn) {
    btn.addEventListener("click", function () {
      state.activeTab = btn.dataset.tab;
      renderTabs();
    });
  });
  var moreToggle = $("#moreDetailsToggle");
  if (moreToggle) {
    moreToggle.addEventListener("click", function () {
      state.moreOpen = !state.moreOpen;
      renderMoreDetails();
    });
  }
  var backBtn = $("#backBtn");
  if (backBtn) {
    backBtn.addEventListener("click", function () {
      if (window.appsmith && typeof appsmith.triggerEvent === "function") {
        appsmith.triggerEvent("onBack");
      }
    });
  }
  document.addEventListener("click", function (e) {
    var dl = e.target.closest("[data-doc-download]");
    if (dl) {
      var index = Number(dl.dataset.docDownload);
      downloadDoc(index);
    }
  });
}

// ============================================================
// Sync Model & Boot Cycle
// ============================================================
function syncWithModel(customModel) {
  var M = customModel || (typeof appsmith !== "undefined" && appsmith.model ? appsmith.model : {});
  currentAppsmithModel = M;
  variantMap = Array.isArray(M.Doc) ? M.Doc : [];
  docCatalogList = Array.isArray(M.documentCatelog) ? M.documentCatelog : Array.isArray(M.documentCatalog) ? M.documentCatalog : [];
  fieldCatalogList = Array.isArray(M.fieldCatelog) ? M.fieldCatelog : Array.isArray(M.fieldCatalog) ? M.fieldCatalog : [];
  groupsList = Array.isArray(M.groups) ? M.groups : [];
  setupEventListeners();
  hydrate();
  render();
}
if (typeof appsmith !== "undefined") {
  if (typeof appsmith.onReady === "function") {
    appsmith.onReady(function () {
      syncWithModel(appsmith.model);
    });
  }
  if (typeof appsmith.onModelChange === "function") {
    appsmith.onModelChange(function (model) {
      if (isInternalUpdate) return;
      syncWithModel(model || appsmith.model);
    });
  }
} else {
  syncWithModel();
}
